    "keySignature": "Eb Major",
    "scriptureAnchor": {
      "reference": "Colossians 3:16",
      "text": "Let the word of Christ dwell in you richly in all wisdom; teaching and admonishing one another in psalms and hymns and spiritual songs, singing with grace in your hearts to the Lord.",
      "book": "Colossians",
      "chapter": 3,
      "verse": 16
    },
    "stanzas": [
      {
        "number": 1,
        "text": "Our Father! we would worship\nIn Jesus' holy Name;\nFor He, whate'er our changes,\nFor ever is the same.\nThrough Him Thy children's praises\nAs incense sweet will be;\nAnd songs Thy Spirit raises\nCan want no melody."
      },
      {
        "number": 2,
        "text": "The fire Thy love hath kindled\nShall never be put out;\nThe Spirit keeps it burning\nThough dimmed by sin and doubt:\nO make it burn more brightly\nWith purifying powers!\nThat we may value rightly\nThe grace that made Thee ours."
      }
    ],
